from fastapi import FastAPI, HTTPException, Depends
from sqlalchemy.orm import Session
from typing import Annotated
import requests

app = FastAPI()

# Assuming you have a User model and a get_db dependency
class User:
    def __init__(self, id: int, credits: int):
        self.id = id
        self.credits = credits

def get_user(db: Session, user_id: int) -> User:
    # Simulate fetching user from database
    return User(id=user_id, credits=100)

async def charge_credits(user: User, db: Session):
    if user.credits >= 50:
        user.credits -= 50
        # Simulate updating user in database
        db.commit()
        return True
    else:
        raise HTTPException(status_code=400, detail="Insufficient credits")

@app.post("/generate-image")
async def generate_image(
    user_id: int,
    db: Annotated[Session, Depends(get_db)],
    user: User = Depends(lambda: get_user(db, user_id))
):
    if await charge_credits(user, db):
        try:
            response = await requests.post("https://image-generation-api.com/generate", timeout=10)
            response.raise_for_status()
            return {"image_url": response.json()["url"]}
        except requests.RequestException as e:
            raise HTTPException(status_code=500, detail=f"Image generation failed: {str(e)}")

