import anthropic
from fastapi import HTTPException, status
from typing import Optional

client = anthropic.Client()

async def call_anthropic_api(prompt: str) -> Optional[str]:
    try:
        response = await client.completions.create(
            model="claude-2",
            prompt=prompt,
            max_tokens=1000,
            stop_sequences=["\n\nHuman:"],
        )
        return response.text.strip()
    except anthropic.APIError as e:
        raise HTTPException(status_code=status.HTTP_503_SERVICE_UNAVAILABLE, detail=f"Anthropic API error: {e}")
    except Exception as e:
        raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=f"Unexpected error: {e}")

async def handle_prompt(prompt: str) -> Optional[str]:
    if len(prompt) > 8000:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Prompt exceeds token limit")

    return await call_anthropic_api(prompt)
