import json

def parse_llm_json(llm_result: str) -> dict:
    # Remove the JSON markers if present
    cleaned_result = llm_result.strip().strip('`').replace('```json', '').replace('```', '')

    try:
        return json.loads(cleaned_result)
    except json.JSONDecodeError as e:
        raise ValueError(f"Failed to decode JSON: {e}") from e

