import json
from typing import Any

class PartialJSONDecoder(json.JSONDecoder):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, object_hook=self.object_hook, **kwargs)
        self._partial = ""

    def decode(self, s, _w=json.decoder.WHITESPACE.match):
        s_len = len(s)

        if self._partial:
            s = self._partial + s
            self._partial = ""

        end = 0
        while end < s_len:
            obj, end = self.raw_decode(s, idx=_w(s, end).end())
            yield obj
            if end == s_len:
                break
            elif s[end] != ",":
                raise ValueError("Expecting ',' delimiter")
            end += 1

        if end < s_len:
            self._partial = s[end:]

def parse_json_stream(stream: str) -> Any:
    decoder = PartialJSONDecoder()
    return list(decoder.decode(stream))

